        status=ui.label("Подключение к ноутбуку…",12,Ui.AMBER);ui.pad(status,16,8);root.addView(status);update=ui.label("",13,Ui.ACCENT);ui.pad(update,16,10);update.setVisibility(View.GONE);update.setOnClickListener(v->installUpdate());root.addView(update);
