        questions=ui.col();root.addView(questions);activity=ui.col();var run=ui.row();ui.pad(run,12,0);progress=new ProgressBar(this);progress.setIndeterminateTintList(android.content.res.ColorStateList.valueOf(Ui.ACCENT));run.addView(progress,new LinearLayout.LayoutParams(dp(18),dp(18)));phase=ui.label("",12,Ui.MUTED);ui.pad(phase,8,0);phase.setSingleLine();phase.setEllipsize(TextUtils.TruncateAt.END);phase.setOnClickListener(v->activityDetails());run.addView(phase,new LinearLayout.LayoutParams(0,dp(48),1));now=button("Сейчас",()->send(true,false));now.setTextColor(Ui.AMBER);run.addView(now);stop=ui.icon("stop","Стоп: остановить работу и сохранить очередь",()->command("stop",new JSONObject()));stop.setImageDrawable(new Ui.Glyph("stop",Ui.RED));run.addView(stop,new LinearLayout.LayoutParams(dp(48),dp(48)));activity.addView(run);activity.setVisibility(View.GONE);root.addView(activity);
        queue=ui.col();root.addView(queue);var composer=ui.col();var cp=new LinearLayout.LayoutParams(-1,-2);cp.setMargins(dp(12),dp(8),dp(12),dp(8));composer.setBackground(ui.shape(Ui.PANEL,20));root.addView(composer,cp);attachments=ui.col();composer.addView(attachments);
        input=ui.edit("Задача или уточнение…");input.setBackgroundColor(Color.TRANSPARENT);input.setMinLines(1);input.setMaxLines(5);input.setGravity(Gravity.TOP);input.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE|InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);input.setImeOptions(EditorInfo.IME_FLAG_NO_EXTRACT_UI);composer.addView(input);
