    private void restoreDraft(){applying=true;input.setText(prefs.getString("draft."+selected,""));try{draftAttachments=new JSONArray(prefs.getString("attachments."+selected,"[]"));}catch(Exception ignored){draftAttachments=new JSONArray();}applying=false;renderAttachments();}
    private boolean tight(){return root!=null&&root.getHeight()>0&&root.getHeight()-root.getPaddingTop()-root.getPaddingBottom()<dp(320);}
    private void layoutForSpace(){if(input==null||headerView==null)return;int available=root.getHeight()-root.getPaddingTop()-root.getPaddingBottom();if(available<=0)return;boolean small=available<dp(380),tight=tight();headerView.setVisibility(tight?View.GONE:View.VISIBLE);navView.setVisibility(small?View.GONE:View.VISIBLE);queue.setVisibility(tight?View.GONE:View.VISIBLE);if(queue.getChildCount()>2)queue.getChildAt(2).setVisibility(small?View.GONE:View.VISIBLE);input.setMaxLines(tight?1:small?2:5);if(tight)activity.setVisibility(View.GONE);}
    private ArrayAdapter<String> choiceAdapter(List<String> values){return new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,values){public View getView(int position,View old,ViewGroup parent){var t=(TextView)super.getView(position,old,parent);t.setTextSize(15);t.setTextColor(Ui.TEXT);t.setSingleLine();t.setEllipsize(TextUtils.TruncateAt.END);var arrow=new Ui.Glyph("down",Ui.MUTED);arrow.setBounds(0,0,dp(16),dp(16));t.setCompoundDrawables(null,null,arrow,null);t.setCompoundDrawablePadding(dp(8));return t;}};}
    private void saveDraft(){if(input!=null&&!selected.isEmpty()&&!applying)prefs.edit().putString("draft."+selected,input.getText().toString()).putString("attachments."+selected,draftAttachments.toString()).apply();}
    private JSONObject session(){for(int i=0;i<array(snapshot,"sessions").length();i++){var s=array(snapshot,"sessions").optJSONObject(i);if(selected.equals(s.optString("id")))return s;}return new JSONObject();}
    private JSONObject conversation(){return object(snapshot,"conversation");}
    private void controls(){if(send==null||input==null)return;boolean writable=!busy&&pendingUrgent==null&&!selected.isEmpty()&&session().optBoolean("active",true);boolean filled=!input.getText().toString().trim().isEmpty()||draftAttachments.length()>0;send.setEnabled(writable&&filled&&uploading==0);send.setAlpha(send.isEnabled()?1:.35f);now.setEnabled(writable&&filled&&uploading==0);if(input.isEnabled()!=writable)input.setEnabled(writable);modelButton.setEnabled(!selected.isEmpty());var s=session();activity.setVisibility(!tight()&&(s.optBoolean("running")||s.optBoolean("queuePaused")&&filled)?View.VISIBLE:View.GONE);input.setHint(s.optInt("queued")>0?"Дополнить последнее в очереди…":"Задача или уточнение…");send.setContentDescription(s.optInt("queued")>0?"Дополнить":s.optBoolean("running")||s.optBoolean("queuePaused")?"В очередь":"Отправить");}
    private void poll(){if(connection==null||input==null||polling)return;polling=true;String id=selected;var c=connection;io.execute(()->{try{var data=c.request("/state"+(id.isEmpty()?"":"?session="+id),null);main.post(()->{polling=false;if(connection!=c)return;if(!id.equals(selected)){poll();return;}snapshot=data;online=true;render();});if(System.currentTimeMillis()-lastUpdate>300_000){lastUpdate=System.currentTimeMillis();checkUpdate(c);}}catch(Exception e){main.post(()->{polling=false;online=false;if(status!=null){status.setText(pendingUrgent==null?"Нет связи · черновик сохранён · повторяем подключение":"Сообщение сохранено · отправим после подключения");status.setVisibility(View.VISIBLE);}});}});}
    private void render(){if(input==null)return;if(selected.isEmpty()){for(int i=0;i<array(snapshot,"sessions").length();i++){var s=array(snapshot,"sessions").optJSONObject(i);if(s.optBoolean("active")){choose(s.optString("id"));return;}}status.setText("Добавьте первый проект на ноутбуке");return;}
        var s=session();title.setText(s.optString("title","Сессия"));projectTitle.setText(projectName(s.optString("projectId")));status.setVisibility(pendingUrgent==null?View.GONE:View.VISIBLE);status.setText("Доставляем сообщение…");boolean running=s.optBoolean("running"),paused=s.optBoolean("queuePaused");var p=object(s,"progress");activity.setVisibility(running||paused?View.VISIBLE:View.GONE);progress.setVisibility(running?View.VISIBLE:View.GONE);stop.setVisibility(running?View.VISIBLE:View.GONE);long seconds=Math.max(0,(System.currentTimeMillis()-p.optLong("startedAt",System.currentTimeMillis()))/1000);phase.setText(running?s.optString("phase","Работает")+" · "+(seconds/60)+":"+String.format(Locale.ROOT,"%02d",seconds%60):"Очередь на паузе");now.setText(running?"Перебить":"Сейчас");var pref=object(s,"preferences");modelButton.setText((pref.isNull("model")?"Codex":pref.optString("model","Codex"))+" · "+effortLabel(pref.optString("reasoningEffort","")));
        timeline.render(array(conversation(),"messages"),conversation().optString("live",""));renderQueue();renderQuestions();renderQueueDialog();controls();if(object(s,"quotaWait").optBoolean("waiting")){status.setVisibility(View.VISIBLE);status.setText(object(s,"quotaWait").optBoolean("autoResume")?"Ждём квоту · продолжим автоматически":"Нет квоты · автопродолжение выключено");}markSeen();if(pendingUrgent!=null&&!busy)retryUrgent();}
    private String projectName(String id){for(int i=0;i<array(snapshot,"projects").length();i++){var p=array(snapshot,"projects").optJSONObject(i);if(id.equals(p.optString("id")))return p.optString("title",p.optString("name","Проект"));}return "Tethium";}
    private void choose(String id){saveDraft();selected=id;prefs.edit().putString("session",id).apply();restoreDraft();catalogSession="";queueSignature="";questionSignature="";seen="";selectedJobs.clear();timeline.reset(id);title.setText(session().optString("title","Загрузка…"));controls();poll();}
    private void markSeen(){if(!alive||!online||timeline==null||!timeline.bottom()||selected.isEmpty()||queueDialog!=null&&queueDialog.isShowing())return;var att=object(session(),"attention");String runId=att.optString("version");if(runId.isEmpty()||runId.equals(seen)||!att.optBoolean("unread"))return;seen=runId;String id=selected;io.execute(()->{try{connection.request("/sessions/"+id+"/seen",Connection.json("version",Long.parseLong(runId)));}catch(Exception ignored){main.post(()->seen="");}});}

    private void renderQueue(){var jobs=array(conversation(),"queued");boolean paused=session().optBoolean("queuePaused");String sig=jobs.toString()+paused;if(sig.equals(queueSignature))return;queueSignature=sig;queue.removeAllViews();if(jobs.length()==0&&!paused)return;ui.line(queue);var bar=ui.row();ui.pad(bar,8,0);queueButton=button("Очередь · "+jobs.length()+(paused?" · пауза":""),this::openQueue);queueButton.setSingleLine();queueButton.setEllipsize(TextUtils.TruncateAt.END);queueButton.setTextColor(Ui.ACCENT);queueButton.setBackground(ui.ripple(0,12));queueButton.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);bar.addView(queueButton,new LinearLayout.LayoutParams(0,dp(48),1));if(paused&&jobs.length()>0)bar.addView(button("Продолжить",()->command("queue-resume",new JSONObject())));else bar.addView(ui.icon("chevron","Раскрыть очередь",this::openQueue),new LinearLayout.LayoutParams(dp(48),dp(48)));queue.addView(bar);
        if(jobs.length()>0){var last=jobs.optJSONObject(jobs.length()-1);String text=last.optString("prompt").replace('\n',' ')+(last.optInt("partsCount")>1?" ["+last.optInt("partsCount")+"]":"");var preview=ui.label(text,13,Ui.MUTED);preview.setSingleLine();preview.setEllipsize(TextUtils.TruncateAt.END);preview.setPadding(dp(20),0,dp(20),dp(10));preview.setOnClickListener(v->openQueue());queue.addView(preview);}}
    private void openQueue(){if(queueDialog!=null&&queueDialog.isShowing())return;hideKeyboard();var content=ui.col();ui.pad(content,16,8);var toolbar=ui.row();mergeButton=button("Склеить выбранные",this::mergeJobs);toolbar.addView(mergeButton,new LinearLayout.LayoutParams(0,dp(48),1));toolbar.addView(ui.icon("close","Снять выделение",()->{selectedJobs.clear();queueDialogSignature="";renderQueueDialog();}),new LinearLayout.LayoutParams(dp(48),dp(48)));content.addView(toolbar);ui.gap(content,8);queueItems=ui.col();var sc=new ScrollView(this);sc.addView(queueItems);content.addView(sc,new LinearLayout.LayoutParams(-1,0,1));queueDialog=ui.sheet("Очередь сообщений",content);queueDialog.setOnDismissListener(d->{queueDialog=null;selectedJobs.clear();});queueDialogSignature="";renderQueueDialog();}
    private void renderQueueDialog(){if(queueDialog==null||!queueDialog.isShowing())return;var jobs=array(conversation(),"queued");String sig=jobs.toString()+selectedJobs;if(sig.equals(queueDialogSignature))return;queueDialogSignature=sig;var existing=new HashSet<String>();for(int i=0;i<jobs.length();i++)existing.add(jobs.optJSONObject(i).optString("id"));selectedJobs.retainAll(existing);mergeButton.setEnabled(selectedJobs.size()>1);mergeButton.setText(selectedJobs.size()>1?"Склеить · "+selectedJobs.size():"Выберите сообщения");queueItems.removeAllViews();if(jobs.length()==0){var empty=ui.label("Очередь пуста. Новые сообщения появятся здесь, пока агент работает или очередь на паузе.",16,Ui.MUTED);ui.pad(empty,8,24);queueItems.addView(empty);}
        for(int i=0;i<jobs.length();i++){var job=jobs.optJSONObject(i);String id=job.optString("id");var card=ui.col();card.setBackground(ui.shape(selectedJobs.contains(id)?0xff34304b:Ui.BG,16));ui.pad(card,12,8);var head=ui.row();var select=new CheckBox(this);select.setButtonTintList(android.content.res.ColorStateList.valueOf(Ui.ACCENT));select.setChecked(selectedJobs.contains(id));select.setText(""+(i+1)+(job.optBoolean("urgent")?" · сейчас":"")+(job.optInt("partsCount")>1?" · ["+job.optInt("partsCount")+"]":""));select.setTextColor(Ui.MUTED);select.setContentDescription("Выбрать сообщение "+(i+1));select.setMinHeight(dp(48));select.setOnCheckedChangeListener((b,on)->{if(on)selectedJobs.add(id);else selectedJobs.remove(id);queueDialogSignature="";renderQueueDialog();});head.addView(select,new LinearLayout.LayoutParams(0,dp(48),1));head.addView(ui.icon("more","Действия с сообщением "+(i+1),()->queueMenu(job)),new LinearLayout.LayoutParams(dp(48),dp(48)));card.addView(head);var text=ui.label(job.optString("prompt"),15,Ui.TEXT);text.setTextIsSelectable(true);text.setLineSpacing(dp(4),1);card.addView(text);ui.gap(card,12);queueItems.addView(card);ui.gap(queueItems,12);if(id.equals(focusJob)){card.setBackground(ui.shape(0xff34304b,16));card.post(()->card.requestRectangleOnScreen(new android.graphics.Rect(0,0,card.getWidth(),Math.min(card.getHeight(),dp(200))),false));focusJob="";}}
    }
    private void queueMenu(JSONObject job){var choices=new ArrayList<String>(Arrays.asList("Вернуть последнюю часть в редактор","Первым","Выше","Ниже"));if(job.optInt("partsCount")>1)choices.add("Разбить на сообщения");choices.add("Копировать текст");choices.add("Удалить…");new AlertDialog.Builder(this).setTitle("Сообщение в очереди").setItems(choices.toArray(new String[0]),(d,n)->{String choice=choices.get(n);if(n==0){if(busy||pendingUrgent!=null)return;enqueueOperation("queue-take",Connection.json("jobId",job.optString("id"),"expectedPrompt",job.optString("prompt"),"draft",input.getText().toString(),"requestId",UUID.randomUUID().toString()));if(queueDialog!=null)queueDialog.dismiss();}else if(n<4)command("queue-move",Connection.json("jobId",job.optString("id"),"direction",new String[]{"first","up","down"}[n-1]));else if(choice.startsWith("Разбить"))enqueueOperation("queue-split",Connection.json("jobId",job.optString("id"),"expectedPrompt",job.optString("prompt"),"requestId",UUID.randomUUID().toString()));else if(choice.startsWith("Копировать"))ui.copy(job.optString("prompt"));else new AlertDialog.Builder(this).setTitle("Удалить сообщение?").setMessage("Будут удалены все его части. Остальная очередь сохранится.").setNegativeButton("Отмена",null).setPositiveButton("Удалить",(x,y)->command("queue-remove",Connection.json("jobId",job.optString("id")))).show();}).show();}
    private void mergeJobs(){var selected=new JSONArray();var jobs=array(conversation(),"queued");for(int i=0;i<jobs.length();i++){var job=jobs.optJSONObject(i);if(selectedJobs.contains(job.optString("id")))selected.put(Connection.json("id",job.optString("id"),"prompt",job.optString("prompt")));}if(selected.length()>1)enqueueOperation("queue-merge",Connection.json("selected",selected,"requestId",UUID.randomUUID().toString()));}

    private void send(boolean urgent,boolean separate){if(uploading>0||busy||pendingUrgent!=null||selected.isEmpty()||input.getText().toString().trim().isEmpty()&&draftAttachments.length()==0)return;var ids=new JSONArray();for(int i=0;i<draftAttachments.length();i++)ids.put(draftAttachments.optJSONObject(i).optString("id"));enqueueOperation(urgent?"interrupt":"run",Connection.json("prompt",input.getText().toString(),"attachments",ids,"separate",separate,"requestId",UUID.randomUUID().toString()));}
    private void enqueueOperation(String action,JSONObject body){if(busy||pendingUrgent!=null)return;saveDraft();pendingUrgent=Connection.json("session",selected,"action",action,"body",body).toString();prefs.edit().putString("pendingUrgent",pendingUrgent).apply();retryUrgent();}
    private void retryUrgent(){if(busy||pendingUrgent==null)return;busy=true;controls();String saved=pendingUrgent;var c=connection;io.execute(()->{try{var task=new JSONObject(saved);String id=task.getString("session"),action=task.optString("action","interrupt");var result=c.request("/sessions/"+id+"/"+action,task.getJSONObject("body"));main.post(()->{pendingUrgent=null;busy=false;prefs.edit().remove("pendingUrgent").apply();if(action.equals("run")||action.equals("interrupt")){prefs.edit().remove("draft."+id).remove("attachments."+id).apply();if(selected.equals(id)){applying=true;input.setText("");draftAttachments=new JSONArray();applying=false;renderAttachments();focusJob=result.optString("jobId");}Toast.makeText(this,action.equals("interrupt")?"Правка выполняется сейчас":"Сообщение доставлено",Toast.LENGTH_SHORT).show();}else if(action.equals("queue-take")){String text=result.optString("draft");prefs.edit().putString("draft."+id,text).apply();if(selected.equals(id)){input.setText(text);input.setSelection(input.length());input.requestFocus();((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showSoftInput(input,InputMethodManager.SHOW_IMPLICIT);}}else selectedJobs.clear();controls();poll();});}catch(Connection.ApiException rejected){main.post(()->{pendingUrgent=null;busy=false;prefs.edit().remove("pendingUrgent").apply();controls();poll();});error(rejected);}catch(Exception e){main.post(()->{busy=false;controls();status.setText("Изменение сохранено · повторим после подключения");status.setVisibility(View.VISIBLE);});}});}
    private void command(String action,JSONObject body){commandFor(selected,action,body);}
    private void commandFor(String id,String action,JSONObject body){io.execute(()->{try{connection.request("/sessions/"+id+"/"+action,body);main.post(this::poll);}catch(Exception e){error(e);}});}
    private void sendMenu(){new AlertDialog.Builder(this).setTitle("Сообщение").setItems(new String[]{"Отправить обычным способом","Отдельным сообщением в очередь","Прервать и выполнить сейчас","Развернуть редактор","Стоп · сохранить очередь"},(d,n)->{if(n==4)command("stop",new JSONObject());else if(n==3)editor();else send(n==2,n==1);}).show();}
    private void editor(){if(!input.isEnabled())return;var content=ui.col();ui.pad(content,16,8);var edit=ui.edit("Задача или уточнение…");edit.setGravity(Gravity.TOP);edit.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE);edit.setText(input.getText());content.addView(edit,new LinearLayout.LayoutParams(-1,0,1));var dialog=ui.sheet("Редактор сообщения",content);edit.addTextChangedListener(watch(()->input.setText(edit.getText())));content.addView(ui.primary("Готово",dialog::dismiss));edit.requestFocus();}
    private TextWatcher watch(Runnable r){return new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){r.run();}public void afterTextChanged(Editable e){}};}
    private void hideKeyboard(){if(input!=null)((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(input.getWindowToken(),0);}

    private void sessions(){hideKeyboard();var content=ui.col();ui.pad(content,16,8);var search=ui.edit("Найти проект или сессию");search.setSingleLine();content.addView(search);ui.gap(content,12);var sc=new ScrollView(this);var list=ui.col();sc.addView(list);content.addView(sc,new LinearLayout.LayoutParams(-1,0,1));var inactive=ui.col();inactive.setVisibility(View.GONE);var archiveScroll=new ScrollView(this);archiveScroll.addView(inactive);content.addView(button("Неактивные сессии",()->archiveScroll.setVisibility(archiveScroll.getVisibility()==View.GONE?View.VISIBLE:View.GONE)));archiveScroll.setVisibility(View.GONE);content.addView(archiveScroll,new LinearLayout.LayoutParams(-1,dp(180)));inactive.setVisibility(View.VISIBLE);var dialog=ui.sheet("Проекты и сессии",content);
        Runnable fill=()->{list.removeAllViews();inactive.removeAllViews();String filter=search.getText().toString().toLowerCase(Locale.ROOT);var projects=array(snapshot,"projects");var all=array(snapshot,"sessions");for(int p=0;p<projects.length();p++){var project=projects.optJSONObject(p);String pid=project.optString("id"),name=projectName(pid);var group=ui.col();var archived=ui.col();var h=ui.row();var heading=button("▾  "+name,()->{});heading.setOnClickListener(v->{boolean closed=group.getVisibility()!=View.GONE;group.setVisibility(closed?View.GONE:View.VISIBLE);heading.setText((closed?"▸  ":"▾  ")+name);});heading.setTextColor(Ui.ACCENT);heading.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);h.addView(heading,new LinearLayout.LayoutParams(0,dp(48),1));h.addView(ui.icon("plus","Новая сессия: "+name,()->newSession(pid,dialog)),new LinearLayout.LayoutParams(dp(48),dp(48)));int activeCount=0,inactiveCount=0;
            for(int i=0;i<all.length();i++){var s=all.optJSONObject(i);if(!pid.equals(s.optString("projectId"))||!(name+" "+s.optString("title")).toLowerCase(Locale.ROOT).contains(filter))continue;var row=ui.row();row.setBackground(ui.ripple(s.optString("id").equals(selected)?Ui.RAISED:0,12));var txt=ui.col();ui.pad(txt,12,12);var t=ui.label(s.optString("title"),15,Ui.TEXT);t.setMaxLines(2);txt.addView(t);ui.gap(txt,5);String state=s.optBoolean("running")?s.optString("phase","Работает"):s.optBoolean("queuePaused")?"На паузе":s.optInt("queued")>0?"В очереди · "+s.optInt("queued"):"Готова к работе";txt.addView(ui.label(state,12,Ui.MUTED));row.addView(txt,new LinearLayout.LayoutParams(0,-2,1));String attention=object(s,"attention").optString("kind");if(!attention.isEmpty()){var dot=ui.label("●",13,attention.equals("question")?Ui.AMBER:Ui.ACCENT);dot.setContentDescription(attention.equals("question")?"Ожидает ответа":"Новый результат");ui.pad(dot,12,0);row.addView(dot);}row.setOnClickListener(v->{dialog.dismiss();choose(s.optString("id"));});row.setOnLongClickListener(v->{sessionActions(s,dialog);return true;});if(s.optBoolean("active")){group.addView(row);activeCount++;}else{archived.addView(row);inactiveCount++;}}
            if(activeCount>0||filter.isEmpty()){list.addView(h);list.addView(group);ui.gap(list,12);}if(inactiveCount>0){inactive.addView(ui.label(name,13,Ui.ACCENT));inactive.addView(archived);}}if(list.getChildCount()==0)list.addView(ui.label("Ничего не найдено",15,Ui.MUTED));};fill.run();search.addTextChangedListener(watch(fill));}
    private void newSession(String project,Dialog parent){var edit=ui.edit("Название сессии");new AlertDialog.Builder(this).setTitle("Новая сессия").setView(edit).setNegativeButton("Отмена",null).setPositiveButton("Создать",(d,n)->{String name=edit.getText().toString().trim();io.execute(()->{try{var result=connection.request("/sessions",Connection.json("projectId",project,"title",name.isEmpty()?"Новая сессия":name));main.post(()->{parent.dismiss();choose(result.optString("id"));});}catch(Exception e){error(e);}});}).show();}
    private void sessionActions(JSONObject s,Dialog parent){new AlertDialog.Builder(this).setTitle(s.optString("title")).setItems(new String[]{"Переименовать",s.optBoolean("active")?"Деактивировать":"Вернуть в активные"},(d,n)->{if(n==0){var e=ui.edit("Название");e.setText(s.optString("title"));new AlertDialog.Builder(this).setTitle("Название сессии").setView(e).setNegativeButton("Отмена",null).setPositiveButton("Сохранить",(a,b)->{commandFor(s.optString("id"),"rename",Connection.json("title",e.getText().toString()));if(parent!=null)parent.dismiss();}).show();}else{commandFor(s.optString("id"),"active",Connection.json("active",!s.optBoolean("active")));if(parent!=null)parent.dismiss();}}).show();}

    private void history(boolean searchMode){hideKeyboard();var content=ui.col();ui.pad(content,16,8);var search=ui.edit(searchMode?"Поиск по всем сообщениям":"Найти запрос");search.setSingleLine();content.addView(search);ui.gap(content,8);var list=ui.col();var sc=new ScrollView(this);sc.addView(list);content.addView(sc,new LinearLayout.LayoutParams(-1,0,1));var dialog=ui.sheet(searchMode?"Поиск в разговоре":"Запросы в разговоре",content);Runnable fill=()->{list.removeAllViews();String q=search.getText().toString().toLowerCase(Locale.ROOT);var all=array(conversation(),"messages");int count=0;for(int i=all.length()-1;i>=0;i--){var m=all.optJSONObject(i);String text=m.optString("text");if((!searchMode&&!m.optString("role").equals("user"))||!text.toLowerCase(Locale.ROOT).contains(q))continue;int found=text.toLowerCase(Locale.ROOT).indexOf(q);String excerpt=text.substring(Math.max(0,found-45),Math.min(text.length(),Math.max(0,found-45)+200)).replace('\n',' ');var item=button((m.optString("role").equals("user")?"Вы · ":"Codex · ")+excerpt,()->{dialog.dismiss();timeline.jump(m.optLong("sequence"));});item.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);item.setMaxLines(3);item.setEllipsize(TextUtils.TruncateAt.END);ui.pad(item,12,12);list.addView(item);ui.gap(list,8);if(++count==100)break;}if(count==0)list.addView(ui.label(q.isEmpty()?"Здесь появятся ваши запросы":"Ничего не найдено",15,Ui.MUTED));};fill.run();search.addTextChangedListener(watch(fill));}
