    private void modelSettings(){String id=selected;io.execute(()->{try{var result=connection.request("/models?session="+id,null);main.post(()->{if(!id.equals(selected))return;catalog=new JSONArray();var data=array(result,"data");var auto=Connection.json("model",JSONObject.NULL,"displayName","Из настроек Codex");for(int i=0;i<data.length();i++){var m=data.optJSONObject(i);if(m.optString("model").equals(result.optString("configuredModel"))||result.optString("configuredModel").isEmpty()&&m.optBoolean("isDefault"))auto=Connection.json("model",JSONObject.NULL,"displayName","Авто · "+m.optString("displayName",m.optString("model")),"supportedReasoningEfforts",m.optJSONArray("supportedReasoningEfforts"));}catalog.put(auto);for(int i=0;i<data.length();i++)catalog.put(data.optJSONObject(i));var preferred=object(session(),"preferences");String saved=preferred.isNull("model")?"":preferred.optString("model");boolean found=saved.isEmpty();for(int i=0;i<catalog.length();i++)if(saved.equals(catalog.optJSONObject(i).optString("model")))found=true;if(!found)catalog.put(Connection.json("model",saved,"displayName",saved));showModelSettings();});}catch(Exception e){error(e);}});}
    private void showModelSettings(){var content=ui.col();ui.pad(content,20,12);content.addView(ui.label("Модель",13,Ui.MUTED));var model=new Spinner(this);var effort=new Spinner(this);model.setBackground(ui.shape(Ui.RAISED,12));effort.setBackground(ui.shape(Ui.RAISED,12));ui.pad(model,8,0);ui.pad(effort,8,0);var names=new ArrayList<String>();var pref=object(session(),"preferences");int index=0;for(int i=0;i<catalog.length();i++){var m=catalog.optJSONObject(i);names.add(m.optString("displayName",m.optString("model")));if(!m.isNull("model")&&m.optString("model").equals(pref.optString("model")))index=i;}model.setAdapter(choiceAdapter(names));content.addView(model,new LinearLayout.LayoutParams(-1,dp(56)));ui.gap(content,20);content.addView(ui.label("Усилие",13,Ui.MUTED));content.addView(effort,new LinearLayout.LayoutParams(-1,dp(56)));var values=new ArrayList<String>();final boolean[] first={true};model.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int pos,long item){values.clear();values.add("");var labels=new ArrayList<String>();labels.add("Авто");var supported=array(catalog.optJSONObject(pos),"supportedReasoningEfforts");for(int j=0;j<supported.length();j++){var o=supported.optJSONObject(j);String value=o==null?supported.optString(j):o.optString("reasoningEffort");values.add(value);labels.add(effortLabel(value));}String saved=first[0]?pref.optString("reasoningEffort",""):"";first[0]=false;if(!saved.isEmpty()&&!values.contains(saved)){values.add(saved);labels.add(effortLabel(saved));}effort.setAdapter(choiceAdapter(labels));effort.setSelection(Math.max(0,values.indexOf(saved)));}});model.setSelection(index);ui.gap(content,24);content.addView(ui.label("Настройки применяются к следующему запуску. Текущая работа продолжится с прежними параметрами.",14,Ui.MUTED));var frame=ui.col();var sc=new ScrollView(this);sc.addView(content);frame.addView(sc,new LinearLayout.LayoutParams(-1,-1));var dialog=ui.sheet("Модель и усилие",frame);ui.compact(dialog,440);ui.gap(content,24);content.addView(ui.primary("Применить",()->{if(values.isEmpty())return;var m=catalog.optJSONObject(model.getSelectedItemPosition());String e=values.get(Math.max(0,effort.getSelectedItemPosition()));command("settings",Connection.json("model",m.isNull("model")?JSONObject.NULL:m.optString("model"),"reasoningEffort",e.isEmpty()?JSONObject.NULL:e));dialog.dismiss();}));}
    private String effortLabel(String e){return switch(e){case "low"->"Низкое";case "medium"->"Среднее";case "high"->"Высокое";case "xhigh"->"Максимум";case "minimal"->"Минимум";case "","null"->"Авто";default->e;};}

    private void renderQuestions(){var req=array(conversation(),"requests");if(req.toString().equals(questionSignature))return;questionSignature=req.toString();questions.removeAllViews();for(int i=0;i<req.length();i++){var q=req.optJSONObject(i);var b=button("Нужен ваш ответ →",()->answer(q));b.setTextColor(Ui.AMBER);questions.addView(b);}}
    private void answer(JSONObject request){var content=ui.col();ui.pad(content,20,12);var inputs=new LinkedHashMap<String,EditText>();var qs=array(object(request,"params"),"questions");if(qs.length()==0){new AlertDialog.Builder(this).setMessage("Этот запрос доступен на ноутбуке").setPositiveButton("OK",null).show();return;}for(int i=0;i<qs.length();i++){var q=qs.optJSONObject(i);content.addView(ui.title(q.optString("question")));ui.gap(content,12);var edit=ui.edit("Ваш ответ");inputs.put(q.optString("id"),edit);var options=array(q,"options");for(int j=0;j<options.length();j++){var option=options.optJSONObject(j);String label=option.optString("label");var b=button(label,()->edit.setText(label));b.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);content.addView(b);if(!option.optString("description").isEmpty()){var desc=ui.label(option.optString("description"),13,Ui.MUTED);ui.pad(desc,12,6);content.addView(desc);}ui.gap(content,4);}content.addView(edit);ui.gap(content,24);}var frame=ui.col();var sc=new ScrollView(this);sc.addView(content);frame.addView(sc,new LinearLayout.LayoutParams(-1,0,1));var dialog=ui.sheet("Ответ агенту",frame);var submit=ui.primary("Ответить",()->{var answers=new JSONObject();try{for(var entry:inputs.entrySet())answers.put(entry.getKey(),Connection.json("answers",new JSONArray().put(entry.getValue().getText().toString())));}catch(Exception ignored){}io.execute(()->{try{connection.request("/answer",Connection.json("id",request.optString("id"),"answer",Connection.json("answers",answers)));main.post(()->{dialog.dismiss();poll();});}catch(Exception e){error(e);}});});frame.addView(submit);}

    private void pickImage(){if(busy||pendingUrgent!=null||selected.isEmpty())return;var intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.setType("image/*");intent.addCategory(Intent.CATEGORY_OPENABLE);intent.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);startActivityForResult(intent,41);}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==41&&result==RESULT_OK&&data!=null){if(data.getClipData()!=null){for(int i=0;i<data.getClipData().getItemCount();i++)upload(data.getClipData().getItemAt(i).getUri());}else if(data.getData()!=null)upload(data.getData());}}
    private void upload(Uri uri){if(selected.isEmpty()||busy||pendingUrgent!=null)return;if(draftAttachments.length()+uploading>=12){Toast.makeText(this,"К одному сообщению можно прикрепить до 12 изображений",Toast.LENGTH_LONG).show();return;}String id=selected;var c=connection;uploading++;controls();Toast.makeText(this,"Добавляем изображение…",Toast.LENGTH_SHORT).show();io.execute(()->{try{byte[] original;try(var in=getContentResolver().openInputStream(uri);var out=new ByteArrayOutputStream()){byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1){if(out.size()+n>24_000_000)throw new IOException("Изображение больше 24 МБ");out.write(b,0,n);}original=out.toByteArray();}var bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(original,0,original.length,bounds);if(bounds.outWidth<=0||bounds.outHeight<=0)throw new IOException("Не удалось прочитать изображение");var options=new BitmapFactory.Options();while(Math.max(bounds.outWidth,bounds.outHeight)/Math.max(1,options.inSampleSize)>4096)options.inSampleSize=options.inSampleSize==0?2:options.inSampleSize*2;Bitmap bitmap=BitmapFactory.decodeByteArray(original,0,original.length,options);if(bitmap==null)throw new IOException("Не удалось открыть изображение");byte[] bytes;try(var out=new ByteArrayOutputStream()){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);bytes=out.toByteArray();}finally{bitmap.recycle();}var uploaded=c.request("/attachment",Connection.json("data",android.util.Base64.encodeToString(bytes,android.util.Base64.NO_WRAP)));File thumbnail=new File(getFilesDir(),uploaded.getString("id")+".png");try(var out=new FileOutputStream(thumbnail)){out.write(bytes);}main.post(()->{try{var items=new JSONArray(prefs.getString("attachments."+id,"[]"));items.put(uploaded);prefs.edit().putString("attachments."+id,items.toString()).apply();if(selected.equals(id)){draftAttachments=items;renderAttachments();}}catch(Exception e){error(e);}finally{uploading--;controls();}});}catch(Exception e){main.post(()->{uploading--;controls();});error(e);}});}
    private void renderAttachments(){if(attachments==null)return;attachments.removeAllViews();if(draftAttachments.length()==0)return;var line=ui.row();ui.pad(line,8,8);for(int i=0;i<draftAttachments.length();i++){var item=draftAttachments.optJSONObject(i);String id=item.optString("id");var tile=ui.col();var image=new ImageView(this);var options=new BitmapFactory.Options();options.inSampleSize=8;image.setImageBitmap(BitmapFactory.decodeFile(new File(getFilesDir(),id+".png").toString(),options));image.setScaleType(ImageView.ScaleType.CENTER_CROP);image.setOnClickListener(v->ImagePreview.show(this,ui,new File(getFilesDir(),id+".png")));image.setContentDescription("Вложенное изображение");tile.addView(image,new LinearLayout.LayoutParams(dp(64),dp(48)));tile.addView(ui.icon("close","Убрать изображение",()->{if(busy||pendingUrgent!=null)return;var rest=new JSONArray();for(int j=0;j<draftAttachments.length();j++)if(!id.equals(draftAttachments.optJSONObject(j).optString("id")))rest.put(draftAttachments.optJSONObject(j));draftAttachments=rest;saveDraft();renderAttachments();controls();}),new LinearLayout.LayoutParams(dp(64),dp(48)));line.addView(tile);}var sc=new HorizontalScrollView(this);sc.addView(line);attachments.addView(sc);}

    private void quota(){var content=ui.col();ui.pad(content,20,16);var q=object(snapshot,"quota");long updated=q.optLong("updatedAt");content.addView(ui.label(updated>0?"Обновлено "+new java.text.SimpleDateFormat("HH:mm",Locale.ROOT).format(new Date(updated))+" · раз в 5 минут":"Данные пока недоступны",13,Ui.MUTED));var buckets=array(q,"buckets");for(int i=0;i<buckets.length();i++){var b=buckets.optJSONObject(i);ui.gap(content,24);content.addView(ui.title(b.optString("label","Codex")));var windows=array(b,"windows");for(int j=0;j<windows.length();j++){var w=windows.optJSONObject(j);int minutes=w.optInt("durationMinutes"),left=w.optInt("remainingPercent");ui.gap(content,16);var count=object(q,"resetCredits");String label=(minutes==10080?"Неделя"+(count.has("availableCount")?" ["+count.optInt("availableCount")+"]":""):minutes>=60?minutes/60+" ч":minutes+" мин")+" · осталось "+left+"%";var period=ui.label(label,16,Ui.TEXT);period.setMinHeight(dp(48));period.setGravity(Gravity.CENTER_VERTICAL);content.addView(period);if(left<=5&&count.optInt("availableCount")>0&&q.optBoolean("resetSupported")){period.setTextColor(Ui.ACCENT);period.setOnClickListener(v->{var popup=new PopupMenu(this,period);popup.getMenu().add("Использовать один сброс…").setOnMenuItemClickListener(item->{resetQuota();return true;});popup.show();});}var bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setProgressTintList(android.content.res.ColorStateList.valueOf(left<=20?Ui.AMBER:Ui.ACCENT));bar.setProgress(left);content.addView(bar,new LinearLayout.LayoutParams(-1,dp(12)));long reset=w.optLong("resetsAt");if(reset>0)content.addView(ui.label("Сброс "+new java.text.SimpleDateFormat("dd.MM HH:mm",Locale.ROOT).format(new Date(reset*1000)),12,Ui.MUTED));}}var frame=ui.col();var sc=new ScrollView(this);sc.addView(content);frame.addView(sc);ui.sheet("Квота Codex",frame);}
    private void resetQuota(){new AlertDialog.Builder(this).setTitle("Использовать один сброс?").setMessage("Это потратит один доступный сброс лимита Codex.").setNegativeButton("Отмена",null).setPositiveButton("Использовать",(d,n)->{String key=prefs.getString("quotaResetRequest",null);if(key==null){key=UUID.randomUUID().toString();prefs.edit().putString("quotaResetRequest",key).apply();}String request=key;io.execute(()->{try{var result=connection.request("/quota/reset",Connection.json("requestId",request,"confirmed",true));prefs.edit().remove("quotaResetRequest").apply();main.post(()->{Toast.makeText(this,switch(result.optString("outcome")){case "reset","alreadyRedeemed"->"Сброс применён";case "noCredit"->"Доступные сбросы закончились";case "nothingToReset"->"Сейчас нечего сбрасывать";default->result.optString("outcome");},Toast.LENGTH_LONG).show();poll();});}catch(Exception e){error(e);}});}).show();}
    private void menu(){new AlertDialog.Builder(this).setTitle("Сессия").setItems(new String[]{"Настройки сессии","Квота Codex","В конец разговора","Проверить обновление","Подключение к ноутбуку",(object(session(),"quotaWait").optBoolean("autoResume")?"☑":"☐")+" Продолжать после появления квоты","Токены и прошлые периоды"},(d,n)->{switch(n){case 0->sessionActions(session(),null);case 1->quota();case 2->timeline.toEnd();case 3->{lastUpdate=0;poll();Toast.makeText(this,"Проверяем обновления",Toast.LENGTH_SHORT).show();}case 4->pairing();case 5->command("quota-auto",Connection.json("enabled",!object(session(),"quotaWait").optBoolean("autoResume")));case 6->UsageSheet.show(this,ui,connection,snapshot);}}).show();}
    private void quote(String text){if(input==null||!input.isEnabled())return;String quoted="> "+text.strip().replace("\n","\n> ");int pos=Math.max(0,input.getSelectionStart());input.getText().insert(pos,(pos>0?"\n\n":"")+quoted+"\n\n");input.requestFocus();((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showSoftInput(input,InputMethodManager.SHOW_IMPLICIT);}
    private void previewFile(String link){String id=selected;io.execute(()->{try{String path=connection.request("/preview",Connection.json("session",id,"file",link)).getString("path");main.post(()->showPreview(path));}catch(Exception e){error(e);}});}
    private void preview(String artifact){String id=selected;io.execute(()->{try{String path=connection.request("/preview",Connection.json("session",id,"artifact",artifact)).getString("path");main.post(()->showPreview(path));}catch(Exception e){error(e);}});}
    // Preview isolation and APK verification are shared with the first release below.
    private void showPreview(String path){var dialog=new Dialog(this,android.R.style.Theme_Material_NoActionBar);var frame=column();frame.addView(button("Закрыть результат",dialog::dismiss));var web=new WebView(this);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setBuiltInZoomControls(true);web.getSettings().setDisplayZoomControls(false);web.getSettings().setLoadWithOverviewMode(true);web.getSettings().setUseWideViewPort(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);String prefix=path.substring(0,path.lastIndexOf('/')+1);var c=connection;
        web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest r){return !"preview.tethium.invalid".equals(r.getUrl().getHost());}public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest r){try{if(!"preview.tethium.invalid".equals(r.getUrl().getHost())||!r.getMethod().equals("GET")||!r.getUrl().getEncodedPath().startsWith(prefix))return empty();var request=c.open(r.getUrl().getEncodedPath());request.setRequestProperty("Authorization","");if(request.getResponseCode()!=200){request.disconnect();return empty();}String mime=request.getContentType();if(mime==null)mime="application/octet-stream";return new WebResourceResponse(mime.split(";")[0],"UTF-8",200,"OK",Collections.singletonMap("Content-Security-Policy","default-src 'self' data:; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; object-src 'none'; frame-src 'none'; connect-src 'self'"),new FilterInputStream(request.getInputStream()){public void close()throws IOException{super.close();request.disconnect();}});}catch(Exception e){return empty();}}private WebResourceResponse empty(){return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));}});
        frame.addView(web,new LinearLayout.LayoutParams(-1,0,1));dialog.setContentView(frame);inset(frame);dialog.setOnDismissListener(d->{web.stopLoading();web.destroy();});dialog.show();web.loadUrl("https://preview.tethium.invalid"+path);
    }
    private void checkUpdate(Connection c){try{
        var release=c.request("/update",null);int installed=getPackageManager().getPackageInfo(getPackageName(),0).versionCode;if(release.getInt("versionCode")<=installed)return;
        File target=new File(getCacheDir(),"tethium.apk"),temp=new File(getCacheDir(),"tethium.apk.part");
        if(!target.exists()||!Connection.sha(java.nio.file.Files.readAllBytes(target.toPath())).equals(release.getString("sha256"))){var request=c.open("/apk");try{if(request.getResponseCode()!=200)throw new IOException("Не удалось скачать обновление");try(var in=request.getInputStream();var out=new FileOutputStream(temp)){byte[] buffer=new byte[16384];int n,total=0;while((n=in.read(buffer))>=0){total+=n;if(total>50_000_000)throw new IOException("Слишком большой APK");out.write(buffer,0,n);}}}finally{request.disconnect();}if(!Connection.sha(java.nio.file.Files.readAllBytes(temp.toPath())).equals(release.getString("sha256")))throw new IOException("Повреждённый APK");verifyApk(temp,installed);java.nio.file.Files.move(temp.toPath(),target.toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);}
        verifyApk(target,installed);main.post(()->{if(update!=null){update.setText("↑ Обновление "+release.optString("versionName")+" скачано · установить");update.setVisibility(View.VISIBLE);}});
    }catch(Exception e){main.post(()->{if(status!=null)status.setContentDescription("Обновления: "+e.getMessage());});}}
    @SuppressWarnings("deprecation") private void verifyApk(File file,int installed)throws Exception{var pm=getPackageManager();var archive=pm.getPackageArchiveInfo(file.toString(),PackageManager.GET_SIGNATURES);var current=pm.getPackageInfo(getPackageName(),PackageManager.GET_SIGNATURES);if(archive==null||!getPackageName().equals(archive.packageName)||archive.versionCode<=installed||!Arrays.equals(archive.signatures,current.signatures))throw new IOException("Подпись или версия APK не совпадает");}
    private void installUpdate(){try{if(!getPackageManager().canRequestPackageInstalls()){startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+getPackageName())));return;}var intent=new Intent(Intent.ACTION_VIEW);intent.setDataAndType(Uri.parse("content://dev.tethium.mobile.update/tethium.apk"),"application/vnd.android.package-archive");intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(intent);}catch(Exception e){error(e);}}
    private void error(Exception e){main.post(()->{if(!isFinishing()&&!isDestroyed())new AlertDialog.Builder(this).setMessage(Objects.toString(e.getMessage(),"Ошибка")).setPositiveButton("OK",null).show();});}
